#!/usr/bin/env python3
"""Generate Angry Birds HTML game"""
import os

HTML = """<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
<title>Angry Birds</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:linear-gradient(180deg,#87CEEB,#98FB98 60%,#228B22);display:flex;justify-content:center;align-items:center;min-height:100vh;overflow:hidden;font-family:Arial,sans-serif;touch-action:none;user-select:none}
#gc{position:relative;border:3px solid #5D4037;border-radius:12px;box-shadow:0 0 40px rgba(0,0,0,.5)}
canvas{display:block;border-radius:9px;cursor:crosshair}
#ui{position:absolute;top:12px;left:12px;right:12px;display:flex;justify-content:space-between;pointer-events:none;z-index:10}
#ui span{color:#fff;font-size:18px;font-weight:bold;text-shadow:2px 2px 4px #000;background:rgba(0,0,0,.5);padding:6px 16px;border-radius:20px}
#msg{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);color:#FFD700;font-size:36px;font-weight:bold;text-shadow:3px 3px 6px #000;pointer-events:none;text-align:center;display:none;z-index:20}
#help{position:absolute;bottom:12px;left:50%;transform:translateX(-50%);color:rgba(255,255,255,.8);font-size:13px;pointer-events:none;text-shadow:1px 1px 2px #000}
</style>
</head>
<body>
<div id="gc">
<canvas id="c"></canvas>
<div id="ui"><span id="sc">Score: 0</span><span id="bd">Birds: 3</span><span id="lv">Level 1</span></div>
<div id="msg"></div>
<div id="help">Drag slingshot to launch birds! Kill all pigs!</div>
</div>
<script>
const C=document.getElementById('c'),X=C.getContext('2d');
const W=C.width=Math.min(window.innerWidth-20,1200);
const H=C.height=Math.min(window.innerHeight-20,700);
const G=0.4,GR=H-50,SX=140,SY=GR-15;
let sc=0,bd=3,lv=1,gs='aim',bird=null,pigs=[],blks=[],pts=[],dq=['red','yellow','blue','red','blue','yellow'];
let ds=null,dp=null;

function M(t,d){const m=document.getElementById('msg');m.textContent=t;m.style.display='block';setTimeout(()=>m.style.display='none',d||2000)}
function U(){document.getElementById('sc').textContent='Score: '+sc;document.getElementById('bd').textContent='Birds: '+bd;document.getElementById('lv').textContent='Level '+lv}

class Bird{
  constructor(x,y,t){this.x=x;this.y=y;this.r=16;this.vx=0;this.vy=0;this.t=t;this.alive=true;this.launched=false;this.trail=[]}
  draw(){
    if(!this.alive)return;
    if(this.trail.length>1){X.beginPath();X.moveTo(this.trail[0].x,this.trail[0].y);for(let i=1;i<this.trail.length;i++)X.lineTo(this.trail[i].x,this.trail[i].y);X.strokeStyle='rgba(255,255,255,.3)';X.lineWidth=3;X.stroke()}
    X.save();X.translate(this.x,this.y);
    if(this.launched){const s=Math.sqrt(this.vx*this.vx+this.vy*this.vy);if(s>0.5)X.rotate(Math.atan2(this.vy,this.vx)+Math.PI/2)}
    const cl={red:'#E53935',yellow:'#FDD835',blue:'#1E88E5',black:'#333'};
    X.fillStyle=cl[this.t]||'#E53935';X.beginPath();X.arc(0,0,this.r,0,Math.PI*2);X.fill();X.strokeStyle='#222';X.lineWidth=2;X.stroke();
    X.fillStyle='#FFF';X.beginPath();X.arc(-5,-6,6,0,Math.PI*2);X.fill();X.fillStyle='#000';X.beginPath();X.arc(-3,-6,3,0,Math.PI*2);X.fill();
    X.fillStyle='#FFF';X.beginPath();X.arc(5,-6,6,0,Math.PI*2);X.fill();X.fillStyle='#000';X.beginPath();X.arc(7,-6,3,0,Math.PI*2);X.fill();
    X.fillStyle='#FF9800';X.beginPath();X.moveTo(8,-3);X.lineTo(20,0);X.lineTo(8,3);X.fill();X.strokeStyle='#E65100';X.lineWidth=1;X.stroke();
    if(this.t==='yellow'){X.fillStyle='#FFC107';X.beginPath();X.moveTo(-4,-this.r);X.lineTo(0,-this.r-9);X.lineTo(4,-this.r);X.fill()}
    X.restore()
  }
  update(){
    if(!this.alive)return;
    this.trail.push({x:this.x,y:this.y});if(this.trail.length>20)this.trail.shift();
    this.vy+=G;this.x+=this.vx;this.y+=this.vy;this.vx*=0.998;
    if(this.y>GR-this.r){this.y=GR-this.r;this.vy*=-0.2;this.vx*=0.65;if(Math.abs(this.vy)<0.3)this.vy=0}
    if(this.x>W+80||this.x<-80||this.y>H+80)this.alive=false
  }
  sp(){return Math.sqrt(this.vx*this.vx+this.vy*this.vy)}
}

class Pig{
  constructor(x,y,s){this.x=x;this.y=y;this.r=s||18;this.alive=true;this.vx=0;this.vy=0}
  draw(){
    if(!this.alive)return;
    X.save();X.translate(this.x,this.y);
    X.fillStyle='#4CAF50';X.beginPath();X.arc(0,0,this.r,0,Math.PI*2);X.fill();
    X.fillStyle='#81C784';X.beginPath();X.arc(0,-2,this.r-3,0,Math.PI*2);X.fill();
    X.strokeStyle='#2E7D32';X.lineWidth=2;X.beginPath();X.arc(0,0,this.r,0,Math.PI*2);X.stroke();
    X.fillStyle='#FFF';X.beginPath();X.arc(-4,-7,4,0,Math.PI*2);X.fill();X.fillStyle='#000';X.beginPath();X.arc(-2,-7,2,0,Math.PI*2);X.fill();
    X.fillStyle='#FFF';X.beginPath();X.arc(4,-7,4,0,Math.PI*2);X.fill();X.fillStyle='#000';X.beginPath();X.arc(6,-7,2,0,Math.PI*2);X.fill();
    X.fillStyle='#E91E63';X.beginPath();X.ellipse(0,3,5,3,0,0,Math.PI*2);X.fill();
    X.restore()
  }
  update(){
    if(!this.alive)return;
    this.vy+=G;this.x+=this.vx;this.y+=this.vy;this.vx*=0.99;
    if(this.y>GR-this.r){this.y=GR-this.r;this.vy*=-0.12;this.vx*=0.65}
    if(this.x<this.r){this.x=this.r;this.vx*=-0.5}
    if(this.x>W-this.r){this.x=W-this.r;this.vx*=-0.5}
  }
}

class Block{
  constructor(x,y,w,h,m){this.x=x;this.y=y;this.w=w;this.h=h;this.m=m||'wood';this.vx=0;this.vy=0;this.alive=true;this.angle=0}
  draw(){
    if(!this.alive)return;
    X.save();X.translate(this.x+this.w/2,this.y+this.h/2);X.rotate(this.angle);
    const cl={wood:'#8D6E63',stone:'#78909C',ice:'#B3E5FC'};
    X.fillStyle=cl[this.m]||'#8D6E63';X.fillRect(-this.w/2,-this.h/2,this.w,this.h);
    X.strokeStyle='#3E2723';X.lineWidth=2;X.strokeRect(-this.w/2,-this.h/2,this.w,this.h);
    if(this.m==='stone'){X.fillStyle='rgba(255,255,255,.15)';X.fillRect(-this.w/2+2,-this.h/2+2,this.w-4,this.h/2-2)}
    X.restore()
  }
  update(){
    if(!this.alive)return;
    this.vy+=G;this.x+=this.vx;this.y+=this.vy;this.vx*=0.99;
    if(this.y+this.h>GR){this.y=GR-this.h;this.vy*=-0.06;this.vx*=0.65}
    if(this.x<0){this.x=0;this.vx*=-0.5}
    if(this.x+this.w>W){this.x=W-this.w;this.vx*=-0.5}
  }
}

function circRect(rx,ry,rw,rh,cx,cy,cr){
  const nx=Math.max(rx,Math.min(cx,rx+rw)),ny=Math.max(ry,Math.min(cy,ry+rh));
  return Math.hypot(cx-nx,cy-ny)<cr
}
function circCirc(x1,y1,r1,x2,y2,r2){return Math.hypot(x1-x2,y1-y2)<r1+r2}

function boom(x,y,c){
  for(let i=0;i<8;i++){const a=Math.random()*Math.PI*2,s=1+Math.random()*4;pts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-2,life:20+Math.random()*20,c})}
}

function loadLevel(n){
  pigs=[];blks=[];pts=[];bird=null;ds=null;dp=null;gs='aim';
  const ww=35,wh=25,bw=60,bh=20;
  if(n===1){
    pigs.push(new Pig(750,GR-20,20));
    blks.push(new Block(700,GR-60,bw,bh,'wood'));blks.push(new Block(760,GR-60,bw,bh,'wood'));
    blks.push(new Block(730,GR-100,bw,bh,'wood'));
  }else if(n===2){
    pigs.push(new Pig(700,GR-20,20));pigs.push(new Pig(800,GR-20,20));
    blks.push(new Block(660,GR-60,bw,bh,'wood'));blks.push(new Block(720,GR-60,bw,bh,'stone'));
    blks.push(new Block(780,GR-60,bw,bh,'stone'));blks.push(new Block(840,GR-60,bw,bh,'wood'));
    blks.push(new Block(690,GR-100,bw,bh,'wood'));blks.push(new Block(810,GR-100,bw,bh,'wood'));
    blks.push(new Block(750,GR-120,bw,bh,'ice'));
  }else{
