    X.fillStyle='#FF9800';X.beginPath();X.moveTo(8,-3);X.lineTo(18,0);X.lineTo(8,3);X.fill();
    if(this.tp==='yellow'){X.fillStyle='#FFC107';X.beginPath();X.moveTo(-3,-this.r);X.lineTo(0,-this.r-8);X.lineTo(3,-this.r);X.fill()}
    if(this.tp==='blue'){X.fillStyle='rgba(255,255,255,.4)';X.beginPath();X.arc(-7,-7,3.5,0,Math.PI*2);X.fill();X.beginPath();X.arc(7,-7,3.5,0,Math.PI*2);X.fill()}
    X.restore()
  }
  update(){
    if(!this.active)return;this.trail.push({x:this.x,y:this.y});if(this.trail.length>20)this.trail.shift();
    this.vy+=G;this.x+=this.vx;this.y+=this.vy;this.vx*=0.998;
    if(this.y>GR-this.r){this.y=GR-this.r;this.vy*=-0.2;this.vx*=0.7;if(Math.abs(this.vy)<0.3)this.vy=0}
    if(this.x>W+60||this.x<-60||this.y>H+60)this.active=false
  }
  speed(){return Math.sqrt(this.vx*this.vx+this.vy*this.vy)}
}

class Pig{
  constructor(x,y,sz){this.x=x;this.y=y;this.r=sz||18;this.alive=true;this.vx=0;this.vy=0}
  draw(){
    if(!this.alive)return;
    X.save();X.translate(this.x,this.y);
    X.fillStyle='#4CAF50';X.beginPath();X.arc(0,0,this.r,0,Math.PI*2);X.fill();X.fillStyle='#81C784';X.beginPath();X.arc(0,-1,this.r-3,0,Math.PI*2);X.fill();
    X.strokeStyle='#2E7D32';X.lineWidth=2;X.beginPath();X.arc(0,0,this.r,0,Math.PI*2);X.stroke();
    X.fillStyle='#FFF';X.beginPath();X.arc(-4,-7,4.5,0,Math.PI*2);X.fill();X.fillStyle='#000';X.beginPath();X.arc(-2,-7,2.2,0,Math.PI*2);X.fill();
    X.fillStyle='#FFF';X.beginPath();X.arc(4,-7,4.5,0,Math.PI*2);X.fill();X.fillStyle='#000';X.beginPath();X.arc(6,-7,2.2,0,Math.PI*2);X.fill();
    X.fillStyle='#E91E63';X.beginPath();X.ellipse(0,3,4,3,0,0,Math.PI*2);X.fill();X.fillStyle='#F48FB1';X.beginPath();X.arc(0,2,2.5,0,Math.PI*2);X.fill();
    X.restore()
  }
  update(){if(!this.alive)return;this.vy+=G;this.x+=this.vx;this.y+=this.vy;this.vx*=0.99;if(this.y>GR-this.r){this.y=GR-this.r;this.vy*=-0.1;this.vx*=0.7}}
}

class Block{
  constructor(x,y,w,h,mt){this.x=x;this.y=y;this.w=w;this.h=h;this.mt=mt||'wood';this.vx=0;this.vy=0;this.alive=true;this.hp=mt==='stone'?3:mt==='ice'?1:2;this.angle=0}
  draw(){
    if(!this.alive)return;
    X.save();X.translate(this.x+this.w/2,this.y+this.h/2);X.rotate(this.angle||0);
    const cl={wood:'#8D6E63',stone:'#78909C',ice:'#B3E5FC'};
    X.fillStyle=cl[this.mt]||'#8D6E63';X.fillRect(-this.w/2,-this.h/2,this.w,this.h);
    X.strokeStyle='#3E2723';X.lineWidth=2;X.strokeRect(-this.w/2,-this.h/2,this.w,this.h);
    if(this.mt==='stone'){X.fillStyle='rgba(255,255,255,.15)';X.fillRect(-this.w/2+3,-this.h/2+3,this.w-6,this.h/2-3)}
    if(this.mt==='ice'){X.fillStyle='rgba(255,255,255,.4)';X.fillRect(-this.w/2+3,-this.h/2+3,this.w-6,this.h-6)}
    X.restore()
  }
  update(){if(!this.alive)return;this.vy+=G;this.x+=this.vx;this.y+=this.vy;this.vx*=0.99;if(this.y+this.h>GR){this.y=GR-this.h;this.vy*=-0.05;this.vx*=0.7}}
}

function rc(rx,ry,rw,rh,cx,cy,cr){
  let nx=Math.max(rx,Math.min(cx,rx+rw)),ny=Math.max(ry,Math.min(cy,ry+rh));
  return(nx-cx)*(nx-cx)+(ny-cy)*(ny-cy)<cr*cr
}

function cc(x1,y1,r1,x2,y2,r2){let dx=x2-x1,dy=y2-y1,dist=Math.sqrt(dx*dx+dy*dy);return dist<r1+r2}

function hitBirdBlock(b,bl){
  if(!rc(bl.x,bl.y,bl.w,bl.h,b.x,b.y,b.r))return;
  bl.hp--;if(bl.hp<=0){bl.alive=false;sc+=50;spawnParts(bl.x+bl.w/2,bl.y+bl.h/2,bl.mt)}
  let nx=b.x-(bl.x+bl.w/2),ny=b.y-(bl.y+bl.h/2),spd=b.speed()*0.4;
  b.vx+=nx*0.05;b.vy+=ny*0.05;bl.vx+=nx*0.02*spd;bl.vy+=ny*0.02*spd;bl.angle+=(Math.random()-0.5)*0.2
}

function hitBirdPig(b,p){
  if(!cc(b.x,b.y,b.r,p.x,p.y,p.r))return;
  p.alive=false;sc+=100;spawnParts(p.x,p.y,'pig');
  let spd=b.speed()*0.3;b.vx*=0.6;b.vy*=0.6;p.vx=(p.x-b.x)*0.05*spd;p.vy=(p.y-b.y)*0.05*spd
}

function spawnParts(x,y,tp){
  let cl=tp==='pig'?'#4CAF50':tp==='stone'?'#78909C':tp==='ice'?'#B3E5FC':'#8D6E63';
  for(let i=0;i<8;i++){let a=Math.random()*Math.PI*2,s=2+Math.random()*4;pts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-2,life:20+Math.random()*20,color:cl})}
}

function levelData(n){
  if(n===1)return{
    pigs:[{x:800,y:GR-20,r:18},{x:900,y:GR-20,r:18}],
    blocks:[{x:780,y:GR-80,w:30,h:80,mt:'wood'},{x:820,y:GR-40,w:80,h:20,mt:'wood'},{x:880,y:GR-80,w:30,h:80,mt:'wood'},{x:850,y:GR-70,w:80,h:20,mt:'ice'}]
  }
  if(n===2)return{
    pigs:[{x:750,y:GR-20,r:18},{x:820,y:GR-80,r:18},{x:890,y:GR-20,r:18}],
    blocks:[{x:730,y:GR-60,w:25,h:60,mt:'wood'},{x:770,y:GR-40,w:90,h:20,mt:'stone'},{x:810,y:GR-80,w:25,h:60,mt:'wood'},{x:870,y:GR-40,w:90,h:20,mt:'stone'},{x:910,y:GR-60,w:25,h:60,mt:'ice'}]
  }
  if(n===3)return{
    pigs:[{x:780,y:GR-20,r:20},{x:850,y:GR-20,r:18},{x:920,y:GR-20,r:20}],
    blocks:[{x:760,y:GR-70,w:25,h:70,mt:'stone'},{x:800,y:GR-40,w:80,h:20,mt:'wood'},{x:840,y:GR-90,w:25,h:70,mt:'stone'},{x:830,y:GR-50,w:60,h:20,mt:'ice'}

