function drawScene(){
  X.fillStyle="#87CEEB";X.fillRect(0,0,W,GR);
  X.fillStyle="#228B22";X.fillRect(0,GR,W,H-GR);
  X.fillStyle="#1B5E20";X.fillRect(0,GR,W,3);
  // clouds
  X.fillStyle="rgba(255,255,255,.7)";
  X.beginPath();X.arc(300,80,40,0,6.28);X.arc(340,70,50,0,6.28);X.arc(380,80,40,0,6.28);X.fill();
  X.beginPath();X.arc(700,120,35,0,6.28);X.arc(735,110,45,0,6.28);X.arc(770,120,35,0,6.28);X.fill();
  // sling
  X.fillStyle="#5D4037";X.fillRect(SX-5,SY-50,10,55);
  X.fillStyle="#795548";X.fillRect(SX-20,SY-55,40,10);
  // aiming line
  if(ds&&dp&&gs==="aim"&&bird){
    X.beginPath();X.moveTo(SX,SY-50);X.lineTo(bird.x,bird.y);
    X.strokeStyle="#8D6E63";X.lineWidth=4;X.stroke();
    // trajectory dots
    var dx=SX-bird.x,dy=(SY-50)-bird.y;
    X.fillStyle="rgba(255,255,255,.5)";
    for(var i=1;i<=6;i++){
      var tx=SX+dx*i*2.5,ty=(SY-50)+dy*i*2.5+0.5*G*i*i*6.25;
      X.beginPath();X.arc(tx,ty,3,0,6.28);X.fill()
    }
  }
  if(bird&&bird.launched&&bird.active){
    X.beginPath();X.moveTo(SX-10,SY-50);X.lineTo(bird.x,bird.y);X.strokeStyle="#8D6E63";X.lineWidth=3;X.stroke();
    X.beginPath();X.moveTo(SX+10,SY-50);X.lineTo(bird.x,bird.y);X.strokeStyle="#8D6E63";X.lineWidth=3;X.stroke()
  }
  // queue
  for(var i=0;i<Math.min(bd-1,3);i++){
    var qx=60-i*30,qy=GR-15;
    var cols={red:"#E53935",yellow:"#FDD835",blue:"#1E88E5"};var tp=bq[i]||"red";
    X.fillStyle=cols[tp];X.beginPath();X.arc(qx,qy,10,0,6.28);X.fill();X.strokeStyle="#333";X.lineWidth=1.5;X.beginPath();X.arc(qx,qy,10,0,6.28);X.stroke()
  }
}

function updateBird(){
  if(!bird||!bird.active)return;
  bird.trail.push({x:bird.x,y:bird.y});if(bird.trail.length>25)bird.trail.shift();
  bird.vy+=G;bird.x+=bird.vx;bird.y+=bird.vy;bird.vx*=0.998;
  if(bird.y>GR-bird.r){bird.y=GR-bird.r;bird.vy*=-0.25;bird.vx*=0.7;if(Math.abs(bird.vy)<0.3)bird.vy=0}
  if(bird.x>W+50||bird.x<-50||bird.y>H+50){bird.active=false}
  // hit pigs
  for(var i=0;i<pigs.length;i++){
    var p=pigs[i];if(!p.alive)continue;
    if(ccc(bird,p)){
      var dx=p.x-bird.x,dy=p.y-bird.y,d=Math.sqrt(dx*dx+dy*dy)||1;
      p.vx+=dx/d*bird.vx*0.6;p.vy+=dy/d*bird.vy*0.6;
      p.alive=false;sc+=500;spawn(p.x,p.y,"#4CAF50");ui()
    }
  }
  // hit blocks
  for(var i=0;i<blks.length;i++){
    var b=blks[i];if(!b.alive)continue;
    if(rcc(b.x,b.y,b.w,b.h,bird.x,bird.y,bird.r)){
      b.hp--;if(b.hp<=0){b.alive=false;sc+=100;spawn(b.x+b.w/2,b.y+b.h/2,b.mt==="wood"?"#8D6E63":b.mt==="ice"?"#B3E5FC":"#78909C");ui()}
      var cx=b.x+b.w/2,cy=b.y+b.h/2,dx=cx-bird.x,dy=cy-bird.y;
      b.vx+=dx*0.02;b.vy+=dy*0.02;
      bird.vx*=0.8;bird.vy*=0.8
    }
  }
}

function updatePigs(){
  for(var i=0;i<pigs.length;i++){
    var p=pigs[i];if(!p.alive)continue;
    p.vy+=G;p.x+=p.vx;p.y+=p.vy;p.vx*=0.99;
    if(p.y>GR-p.r){p.y=GR-p.r;p.vy*=-0.15;p.vx*=0.7}
  }
}

function updateBlocks(){
  for(var i=0;i<blks.length;i++){
    var b=blks[i];if(!b.alive)continue;
    b.vy+=G;b.x+=b.vx;b.y+=b.vy;b.vx*=0.99;
    if(b.y+b.h>GR){b.y=GR-b.h;b.vy*=-0.08;b.vx*=0.7}
    if(b.x<0){b.x=0;b.vx*=-0.5}
    if(b.x+b.w>W){b.x=W-b.w;b.vx*=-0.5}
  }
}

function updateParts(){
  for(var i=pts.length-1;i>=0;i--){
    var p=pts[i];p.vy+=0.15;p.x+=p.vx;p.y+=p.vy;p.life--;
    if(p.life<=0)pts.splice(i,1)
  }
}

function drawParts(){
  for(var i=0;i<pts.length;i++){
    var p=pts[i];X.globalAlpha=p.life/40;X.fillStyle=p.cl;
    X.beginPath();X.arc(p.x,p.y,3,0,6.28);X.fill()
  }
  X.globalAlpha=1
}

var waitTimer=0;

function gameLoop(){
  X.clearRect(0,0,W,H);
  drawScene();
  blks.forEach(drawBlock);
  pigs.forEach(drawPig);
  if(bird)drawBird(bird);
  drawParts();

  if(gs==="aim"&&bird){
    updateParts();updatePigs();updateBlocks();
    bird.x=SX;bird.y=SY-50;
    if(ds&&dp){
      var ddx=dp.x-ds.x,ddy=dp.y-ds.y;
      var dist=Math.sqrt(ddx*ddx+ddy*ddy);
      if(dist>100){ddx=ddx/dist*100;ddy=ddy/dist*100}
      bird.x=SX-ddx*0.5;bird.y=(SY-50)-ddy*0.5
    }
  }
  if(gs==="fly"){
    updateBird();updatePigs();updateBlocks();updateParts();
    if(bird&&!bird.active){gs="wait";waitTimer=60}
    if(allPigsDead()){gs="win";msg("Level Clear! +1000",2500);sc+=1000;ui();waitTimer=120}
  }
  if(gs==="wait"){
    updatePigs();updateBlocks();updateParts();waitTimer--;
    if(waitTimer<=0){
      if(allPigsDead()){gs="win";msg("Level Clear! +1000",2500);sc+=1000;ui();waitTimer=120}
      else if(bd<=0&&!allPigsDead()){gs="lose";msg("Game Over!",3000);waitTimer=150}
      else{bd--;bird=newBird(SX,SY);gs="aim";ui()}
    }
  }
  if(gs==="win"){
    updateParts();waitTimer--;
    if(waitTimer<=0){lv++;if(lv>3){lv=1;sc=0;msg("You Win! Restarting...",2000)}bd=3;bq=["red","yellow","blue","red","blue","yellow"];initLvl()}
  }
  if(gs==="lose"){
    updateParts();waitTimer--;
    if(waitTimer<=0){lv=1;sc=0;bd=3;bq=["red","yellow","blue","red","blue","yellow"];initLvl()}
  }

  requestAnimationFrame(gameLoop)
}

// Input
function getPos(e){
  var r=C.getBoundingClientRect();
  var t=e.touches?e.touches[0]:e;
  return{x:t.clientX-r.left,y:t.clientY-r.top}
}

C.addEventListener("mousedown",function(e){
  if(gs!=="aim"||!bird)return;var p=getPos(e);
  var dx=p.x-bird.x,dy=p.y-bird.y;
  if(dx*dx+dy*dy<900){ds=p;dp=p;bird.active=true}
});
C.addEventListener("mousemove",function(e){if(ds)dp=getPos(e)});
C.addEventListener("mouseup",function(e){
  if(!ds||gs!=="aim"||!bird)return;
  var dx=SX-bird.x,dy=(SY-50)-bird.y;
  bird.vx=dx*0.15;bird.vy=dy*0.15;bird.launched=true;bird.active=true;
  ds=null;dp=null;gs="fly"
});
C.addEventListener("touchstart",function(e){
  e.preventDefault();if(gs!=="aim"||!bird)return;var p=getPos(e);
  var dx=p.x-bird.x,dy=p.y-bird.y;
  if(dx*dx+dy*dy<2500){ds=p;dp=p;bird.active=true}
},{passive:false});
C.addEventListener("touchmove",function(e){e.preventDefault();if(ds)dp=getPos(e)},{passive:false});
C.addEventListener("touchend",function(e){
  e.preventDefault();if(!ds||gs!=="aim"||!bird)return;
  var dx=SX-bird.x,dy=(SY-50)-bird.y;
  bird.vx=dx*0.15;bird.vy=dy*0.15;bird.launched=true;bird.active=true;
  ds=null;dp=null;gs="fly"
});

initLvl();gameLoop();
</script>
</body>
</html>

