const cv=document.getElementById('cv'),ctx=cv.getContext('2d');
cv.width=1200;cv.height=600;
let score=0,level=1,shots=0,isDragging=false,birds=[],pigs=[],blocks=[],projectiles=[];
const G=0.5,GROUND=570;

class Bird{
  constructor(x,y){this.x=x;this.y=y;this.r=18;this.vx=0;this.vy=0;this.active=true;this.launched=false;this.startX=x;this.startY=y;}
  draw(){
    if(!this.active)return;
    ctx.beginPath();ctx.arc(this.x,this.y,this.r,0,Math.PI*2);ctx.fillStyle='#f00';ctx.fill();ctx.strokeStyle='#c00';ctx.lineWidth=2;ctx.stroke();
    ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(this.x-6,this.y-6,5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(this.x+6,this.y-6,5,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#333';ctx.beginPath();ctx.arc(this.x-6,this.y-7,2,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(this.x+6,this.y-7,2,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#f90';ctx.beginPath();ctx.moveTo(this.x,this.y-this.r+5);ctx.lineTo(this.x-7,this.y-this.r);ctx.lineTo(this.x+7,this.y-this.r);ctx.closePath();ctx.fill();
  }
  update(){
    if(!this.active||!this.launched)return;
    this.vy+=G;this.x+=this.vx;this.y+=this.vy;
    if(this.x<this.r||this.x>cv.width-this.r){this.vx*=-0.5;this.x=Math.max(this.r,Math.min(cv.width-this.r,this.x));}
    if(this.y>GROUND-this.r){this.y=GROUND-this.r;this.vy*=-0.3;this.vx*=0.8;if(Math.abs(this.vy)<1){this.vy=0;this.vx*=0.9;}}
    if(this.y<this.r){this.y=this.r;this.vy*=-0.3;}
  }
}

class Pig{
  constructor(x,y){this.x=x;this.y=y;this.r=22;this.vx=0;this.vy=0;this.alive=true;}
  draw(){
    if(!this.alive)return;
    ctx.beginPath();ctx.arc(this.x,this.y,this.r,0,Math.PI*2);ctx.fillStyle='#4CAF50';ctx.fill();ctx.strokeStyle='#388E3C';ctx.lineWidth=2;ctx.stroke();
    ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(this.x-7,this.y-8,6,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(this.x+7,this.y-8,6,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#333';ctx.beginPath();ctx.arc(this.x-7,this.y-9,2.5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(this.x+7,this.y-9,2.5,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#f9a';ctx.beginPath();ctx.ellipse(this.x,this.y+5,6,4,0,0,Math.PI*2);ctx.fill();
  }
  update(){
    if(!this.alive)return;
    this.vy+=G;this.x+=this.vx;this.y+=this.vy;
    if(this.x<this.r||this.x>cv.width-this.r){this.vx*=-0.5;this.x=Math.max(this.r,Math.min(cv.width-this.r,this.x));}
    if(this.y>GROUND-this.r){this.y=GROUND-this.r;this.vy*=-0.3;this.vx*=0.8;if(Math.abs(this.vy)<1){this.vy=0;this.vx*=0.9;}}
  }
}

class Block{
  constructor(x,y,w,h){this.x=x;this.y=y;this.w=w;this.h=h;this.vx=0;this.vy=0;this.alive=true;this.hp=3;}
  draw(){
    if(!this.alive)return;
    let a=this.hp/3;
    ctx.fillStyle=`rgba(139,90,43,${a})`;ctx.fillRect(this.x,this.y,this.w,this.h);
    ctx.strokeStyle='#5D3A1A';ctx.lineWidth=2;ctx.strokeRect(this.x,this.y,this.w,this.h);
  }
  update(){
    if(!this.alive)return;
    this.vy+=G;this.x+=this.vx;this.y+=this.vy;
    if(this.y+this.h>GROUND){this.y=GROUND-this.h;this.vy*=-0.2;this.vx*=0.7;if(Math.abs(this.vy)<1){this.vy=0;this.vx*=0.85;}}
    if(this.x<0||this.x+this.w>cv.width){this.vx*=-0.3;}
  }
}

function checkCollision(a,b){
  if(a instanceof Block){
    let cx=Math.max(a.x,Math.min(b.x,a.x+a.w));
    let cy=Math.max(a.y,Math.min(b.y,a.y+a.h));
    let dx=b.x-cx,dy=b.y-cy;
    return dx*dx+dy*dy < (b.r||18)*(b.r||18);
  }
  if(b instanceof Block){
    let cx=Math.max(b.x,Math.min(a.x,b.x+b.w));
    let cy=Math.max(b.y,Math.min(a.y,b.y+b.h));
    let dx=a.x-cx,dy=a.y-cy;
    return dx*dx+dy*dy < (a.r||18)*(a.r||18);
  }
  let dx=a.x-b.x,dy=a.y-b.y;
  let dist=dx*dx+dy*dy;
  let minDist=((a.r||18)+(b.r||22));
  return dist<minDist*minDist;
}

function resolveCollision(a,b){
  let dx=b.x-a.x,dy=b.y-a.y;
  let dist=Math.sqrt(dx*dx+dy*dy)||1;
  let nx=dx/dist,ny=dy/dist;
  let overlap=((a.r||(a.w/2))+(b.r||(b.w/2)))-dist;
  if(overlap>0){
    if(!(a instanceof Block)){a.x-=nx*overlap/2;a.y-=ny*overlap/2;}
    if(!(b instanceof Block)){b.x+=nx*overlap/2;b.y+=ny*overlap/2;}
  }
  let relVx=a.vx-b.vx,relVy=a.vy-b.vy;
  let relVn=relVx*nx+relVy*ny;
  if(relVn>0){
    let imp=relVn*0.8;
    a.vx-=imp*nx;a.vy-=imp*ny;
    b.vx+=imp*nx;b.vy+=imp*ny;
  }
}

function damageBlock(b,force){
  b.hp-=force;
  if(b.hp<=0){b.alive=false;score+=50;}
}

function handleCollisions(){
  let all=[...birds.filter(b=>b.active&&b.launched),...pigs.filter(p=>p.alive),...blocks.filter(b=>b.alive)];
  for(let i=0;i<all.length;i++){
    for(let j=i+1;j<all.length;j++){
      if(checkCollision(all[i],all[j])){
        resolveCollision(all[i],all[j]);
        let f=Math.abs(all[i].vx-all[j].vx)+Math.abs(all[i].vy-all[j].vy);
        if(all[i] instanceof Block && all[j] instanceof Bird && f>3)damageBlock(all[i],f*0.3);
        if(all[j] instanceof Block && all[i] instanceof Bird && f>3)damageBlock(all[j],f*0.3);
        if(all[i] instanceof Pig && all[j] instanceof Bird && f>5){all[i].alive=false;score+=100;}
        if(all[j] instanceof Pig && all[i] instanceof Bird && f>5){all[j].alive=false;score+=100;}
        if(all[i] instanceof Block && all[j] instanceof Block && f>5){damageBlock(all[i],f*0.2);damageBlock(all[j],f*0.2);}
      }
    }
  }
}

function allPigsDead(){return pigs.every(p=>!p.alive);}
function allBirdsDone(){return birds.every(b=>!b.active||(b.launched&&Math.abs(b.vx)<0.3&&Math.abs(b.vy)<0.3&&b.y>=GROUND-b.r-2));}

function buildLevel(n){
  birds=[];pigs=[];blocks=[];projectiles=[];shots=0;
  birds.push(new Bird(200,GROUND-20));
  if(n>=2)birds.push(new Bird(160,GROUND-20));
  if(n>=3)birds.push(new Bird(240,GROUND-20));

  let bx=800,by=GROUND-60;
  if(n===1){
    blocks.push(new Block(bx,by-40,80,40));
    blocks.push(new Block(bx+20,by-80,40,80));
    pigs.push(new Pig(bx+40,by-100));
  }else if(n===2){
    blocks.push(new Block(bx-30,by-40,60,40));
    blocks.push(new Block(bx+30,by-40,60,40));
    blocks.push(new Block(bx,by-80,60,40));
    pigs.push(new Pig(bx-20,by-100));
    pigs.push(new Pig(bx+20,by-100));
    blocks.push(new Block(900,by-40,40,40));
    pigs.push(new Pig(920,by-60));
  }else{
    blocks.push(new Block(bx-40,by-40,40,40));
    blocks.push(new Block(bx,by-40,40,40));
    blocks.push(new Block(bx+40,by-40,40,40));
    blocks.push(new Block(bx-20,by-80,40,40));
    blocks.push(new Block(bx+20,by-80,40,40));
    blocks.push(new Block(bx,by-120,40,40));
    pigs.push(new Pig(bx-20,by-100));
    pigs.push(new Pig(bx+20,by-100));
    pigs.push(new Pig(bx,by-140));
    blocks.push(new Block(950,by-40,50,50));
    pigs.push(new Pig(975,by-65));
  }
}

let activeBird=null,slingshotX=200,slingshotY=GROUND-20;
let dragStartX=0,dragStartY=0;

function getActiveBird(){
  for(let b of birds){if(b.active&&!b.launched)return b;}
  return null;
}

cv.addEventListener('mousedown',e=>{
  let rect=cv.getBoundingClientRect();
  let mx=(e.clientX-rect.left)*(cv.width/rect.width);
  let my=(e.clientY-rect.top)*(cv.height/rect.height);
  activeBird=getActiveBird();
  if(activeBird&&Math.hypot(mx-activeBird.x,my-activeBird.y)<40){
    isDragging=true;dragStartX=mx;dragStartY=my;
  }
});
cv.addEventListener('mousemove',e=>{
  if(!isDragging||!activeBird)return;
  let rect=cv.getBoundingClientRect();
  dragStartX=(e.clientX-rect.left)*(cv.width/rect.width);
  dragStartY=(e.clientY-rect.top)*(cv.height/rect.height);
});
cv.addEventListener('mouseup',e=>{
  if(!isDragging||!activeBird){isDragging=false;return;}
  isDragging=false;
  let dx=slingshotX-dragStartX,dy=slingshotY-dragStartY;
  let power=Math.min(Math.hypot(dx,dy),150);
  let angle=Math.atan2(dy,dx);
  activeBird.vx=Math.cos(angle)*power*0.15;
  activeBird.vy=Math.sin(angle)*power*0.15;
  activeBird.launched=true;shots++;
  activeBird=null;
});

// Touch support
cv.addEventListener('touchstart',e=>{
  e.preventDefault();
  let rect=cv.getBoundingClientRect();
  let t=e.touches[0];
  let mx=(t.clientX-rect.left)*(cv.width/rect.width);
  let my=(t.clientY-rect.top)*(cv.height/rect.height);
  activeBird=getActiveBird();
  if(activeBird&&Math.hypot(mx-activeBird.x,my-activeBird.y)<50){
    isDragging=true;dragStartX=mx;dragStartY=my;
  }
},{passive:false});
cv.addEventListener('touchmove',e=>{
  e.preventDefault();
  if(!isDragging||!activeBird)return;
  let rect=cv.getBoundingClientRect();
  let t=e.touches[0];
  dragStartX=(t.clientX-rect.left)*(cv.width/rect.width);
  dragStartY=(t.clientY-rect.top)*(cv.height/rect.height);
},{passive:false});
cv.addEventListener('touchend',e=>{
  e.preventDefault();
  if(!isDragging||!activeBird){isDragging=false;return;}
  isDragging=false;
  let dx=slingshotX-dragStartX,dy=slingshotY-dragStartY;
  let power=Math.min(Math.hypot(dx,dy),150);
  let angle=Math.atan2(dy,dx);
  activeBird.vx=Math.cos(angle)*power*0.15;
  activeBird.vy=Math.sin(angle)*power*0.15;
  activeBird.launched=true;shots++;
  activeBird=null;
},{passive:false});

function drawSlingshot(bird){
  if(!bird||bird.launched)return;
  ctx.strokeStyle='#8B4513';ctx.lineWidth=4;
  ctx.beginPath();ctx.moveTo(slingshotX-15,slingshotY);ctx.lineTo(bird.x,bird.y);ctx.lineTo(slingshotX+15,slingshotY);ctx.stroke();
  ctx.fillStyle='#8B4513';ctx.fillRect(slingshotX-18,slingshotY-5,8,40);ctx.fillRect(slingshotX+10,slingshotY-5,8,40);
  ctx.fillStyle='#A0522D';ctx.beginPath();ctx.arc(slingshotX-14,slingshotY-8,8,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(slingshotX+14,slingshotY-8,8,0,Math.PI*2);ctx.fill();
}

function drawGround(){
  ctx.fillStyle='#4a8c3f';ctx.fillRect(0,GROUND,cv.width,cv.height-GROUND);
  ctx.fillStyle='#3d7234';
  for(let i=0;i<cv.width;i+=30){ctx.fillRect(i,GROUND,15,8);}
}

function updateUI(){
  document.getElementById('score').textContent='得分: '+score;
  if(allPigsDead()){document.getElementById('info').textContent='🎉 胜利！所有猪都被消灭了！';}
  else if(allBirdsDone()&&!allPigsDead()){document.getElementById('info').textContent='😞 没打中...点重来再试！';}
  else if(!getActiveBird()&&birds.some(b=>b.launched&&b.active)){document.getElementById('info').textContent='小鸟飞行中...';}
  else{document.getElementById('info').textContent='拉动小鸟，松手发射！';}
}

function gameLoop(){
  ctx.clearRect(0,0,cv.width,cv.height);
  drawGround();

  for(let b of blocks)b.update();
  for(let p of pigs)p.update();
  for(let b of birds)b.update();
  handleCollisions();

  // Remove off-screen birds
  for(let b of birds){
    if(b.launched&&(b.x<-50||b.x>cv.width+50||b.y>cv.height+50))b.active=false;
  }

  for(let b of blocks)b.draw();
  for(let p of pigs)p.draw();

  let cur=getActiveBird();
  if(isDragging&&cur){
    cur.x=dragStartX;cur.y=dragStartY;
    let dx=slingshotX-cur.x,dy=slingshotY-cur.y;
    let dist=Math.hypot(dx,dy);
    if(dist>120){cur.x=slingshotX-dx*120/dist;cur.y=slingshotY-dy*120/dist;}
  }
  drawSlingshot(cur||birds.find(b=>b.active&&!b.launched));
  for(let b of birds)b.draw();

  // Trajectory preview
  if(isDragging&&cur){
    let dx=slingshotX-cur.x,dy=slingshotY-cur.y;
    let power=Math.min(Math.hypot(dx,dy),150);
    let angle=Math.atan2(dy,dx);
    let vx=Math.cos(angle)*power*0.15,vy=Math.sin(angle)*power*0.15;
    let px=cur.x,py=cur.y;
    ctx.fillStyle='rgba(255,255,255,0.3)';
    for(let i=0;i<20;i++){px+=vx;vy+=G;py+=vy;ctx.beginPath();ctx.arc(px,py,3,0,Math.PI*2);ctx.fill();}
  }

  updateUI();
  requestAnimationFrame(gameLoop);
}

function resetLevel(){buildLevel(level);}
function nextLevel(){level++;if(level>3)level=1;buildLevel(level);}

buildLevel(1);
