const match = code.match(/<script>([\s\S]*)<\/script>/);
if(!match){console.log('NO SCRIPT');process.exit(1);}
const js = match[1];
try {
  // Check for syntax errors only - don't execute
  new Function(js);
  console.log('SYNTAX OK');
} catch(e) {
  console.log('SYNTAX ERROR:', e.message);
}
// Check for specific issues
console.log('---');
const lines = code.split('\n');
lines.forEach((l,i) => {
  if(l.includes('allBirdsDone') || l.includes('undefined') || l.includes('null') || l.includes('TypeError')) {
    console.log('L'+(i+1)+':', l.trim());
  }
});
"

